import React from 'react';
import { Card, Typography, Row, Col } from 'antd';
import TextWindow from './TextWindow';
import ImageWindow from './ImageWindow';
import ImageTextWindow from './ImageTextWindow';

const { Title, Paragraph } = Typography;

function Window(props) {
    const { type, content, image, text } = props;

    let windowContent;

    switch (type) {
        case 'text':
            windowContent = (
                <Card bordered={false}>
                    <TextWindow text={content} />
                </Card>
            );
            break;
        case 'image':
            windowContent = (
                <Card cover={<img src={image} alt={content} />}>
                    <Paragraph>{content}</Paragraph>
                </Card>
            );
            break;
        case 'imageWithText':
            windowContent = (
                <Card cover={<img src={content.image} alt="Image with text" />}>
                    <Paragraph>{content.text}</Paragraph>
                </Card>
            );
            break;
        default:
            windowContent = (
                <Card>
                    <Paragraph>No content available</Paragraph>
                </Card>
            );
    }

    return (
        <div className="window">
            <Row justify="center">
                <Col span={8}>
                    <Card style={{ width: '100%' }}>
                        {windowContent}
                    </Card>
                </Col>
            </Row>
        </div>
    );
}

export default Window;
